```python
def flatten_list(nested_list):
    flat_list = []

    def flatten(element):
        if isinstance(element, list):
            for sub_element in element:
                flatten(sub_element)
        else:
            flat_list.append(element)

    for element in nested_list:
        flatten(element)

    return flat_list

# Example usage:
